import * as fs from "frida-fs";
import { Buffer } from "buffer";
import { hexStringToBytes } from "../lib/helpers.js";
import { getApplicationContext, wrapJavaPerform, Java } from "./lib/libjava.js";
export const exists = (path) => {
    // -- Sample Java
    //
    // File path = new File(".");
    // Boolean e = path.exists();
    return wrapJavaPerform(() => {
        const file = Java.use("java.io.File");
        const currentFile = file.$new(path);
        return currentFile.exists();
    });
};
export const readable = (path) => {
    // -- Sample Java Code
    //
    // File d = new File(".");
    // d.canRead();
    return wrapJavaPerform(() => {
        const file = Java.use("java.io.File");
        const currentFile = file.$new(path);
        return currentFile.canRead();
    });
};
export const writable = (path) => {
    // -- Sample Java Code
    //
    // File d = new File(".");
    // d.canWrite();
    return wrapJavaPerform(() => {
        const file = Java.use("java.io.File");
        const currentFile = file.$new(path);
        return currentFile.canWrite();
    });
};
export const pathIsFile = (path) => {
    // -- Sample Java Code
    //
    // File d = new File(".");
    // d.isFile();
    return wrapJavaPerform(() => {
        const file = Java.use("java.io.File");
        const currentFile = file.$new(path);
        return currentFile.isFile();
    });
};
export const pwd = () => {
    // -- Sample Java
    //
    // getApplicationContext().getFilesDir().getAbsolutePath()
    return wrapJavaPerform(() => {
        const context = getApplicationContext();
        return context.getFilesDir().getAbsolutePath().toString();
    });
};
// heavy lifting is done in frida-fs here.
export const readFile = (path) => {
    if (fs.statSync(path).size == 0)
        return Buffer.alloc(0);
    return fs.readFileSync(path);
};
// heavy lifting is done in frida-fs here.
export const writeFile = (path, data) => {
    const writeStream = fs.createWriteStream(path);
    writeStream.on("error", (error) => {
        throw error;
    });
    writeStream.write(hexStringToBytes(data));
    writeStream.end();
};
export const deleteFile = (path) => {
    // -- Sample Java Code
    //
    // File d = new File(".");
    // d.delete();
    return wrapJavaPerform(() => {
        const file = Java.use("java.io.File");
        const currentFile = file.$new(path);
        return currentFile.delete();
    });
};
export const ls = (p) => {
    // -- Sample Java Code
    //
    // File d = new File(".");
    // File[] files = d.listFiles();
    // Log.e(getClass().getName(), "Files: " + files.length);
    // for (int i = 0; i < files.length; i++) {
    //     Log.e(getClass().getName(),
    //             files[i].getName() + ": " + files[i].canRead()
    //             + " " + files[i].lastModified()
    //             + " " + files[i].length()
    //     );
    // }
    return wrapJavaPerform(() => {
        const file = Java.use("java.io.File");
        const directory = file.$new(p);
        const response = {
            files: {},
            path: p,
            readable: directory.canRead(),
            writable: directory.canWrite(),
        };
        if (!response.readable) {
            return response;
        }
        // get a listing of the files in the directory
        const files = directory.listFiles();
        for (const f of files) {
            response.files[f.getName()] = {
                attributes: {
                    isDirectory: f.isDirectory(),
                    isFile: f.isFile(),
                    isHidden: f.isHidden(),
                    lastModified: f.lastModified(),
                    size: f.length(),
                },
                fileName: f.getName(),
                readable: f.canRead(),
                writable: f.canWrite(),
            };
        }
        return response;
    });
};
